def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers = list(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]

    def route_load(r):
        s = 0
        for v in r:
            s += demands[v]
        return s

    def route_cost(r):
        if not r:
            return 0
        c = matrix[depot][r[0]] + matrix[r[-1]][depot]
        for i in range(len(r) - 1):
            c += matrix[r[i]][r[i + 1]]
        return c

    def total_cost(rs):
        s = 0
        for r in rs:
            s += route_cost(r)
        return s

    # Deterministic Clarke-Wright savings initialization with capacity-aware merging
    unassigned = set(customers)
    parent = {i: i for i in customers}
    left = {i: i for i in customers}
    right = {i: i for i in customers}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return ra
        parent[rb] = ra
        # left of merged = left[ra] if a is right end, otherwise consistent by construction
        # right of merged = right[rb]
        return ra

    # Precompute savings for ordered pairs (i,j), where merge connects end of i-route to start of j-route
    savings = []
    for i in customers:
        for j in customers:
            if i == j:
                continue
            # saving if i and j are consecutive in same route
            s = matrix[depot][i] + matrix[depot][j] - matrix[i][j]
            savings.append((s, i, j))
    # Sort descending saving; tie-break deterministic by i then j
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    # Track current route loads and endpoints per component
    comp_load = {i: demands[i] for i in customers}
    # For each node-as-component representative, store current route endpoints
    # We'll store actual route lists after merges, but during merging we need endpoints:
    comp_left_node = {i: i for i in customers}
    comp_right_node = {i: i for i in customers}
    # Also need pointers to sequences for deterministic reconstruction; use successor/predecessor maps
    # Pred[x]=y means x precedes y in its component chain; Succ[x]=y likewise.
    pred = {i: None for i in customers}
    succ = {i: None for i in customers}

    # Merge only if i is a route right end and j is a route left end (in current chains),
    # and they are different components, and capacity allows.
    # This yields a set of disjoint chains; we'll reconstruct routes from these chains.
    for s, i, j in savings:
        ri, rj = find(i), find(j)
        if ri == rj:
            continue
        # i must be right end, j must be left end
        if comp_right_node[ri] != i:
            continue
        if comp_left_node[rj] != j:
            continue
        new_load = comp_load[ri] + comp_load[rj]
        if new_load > capacity:
            continue
        # Link i -> j
        succ[i] = j
        pred[j] = i
        # Union components
        # Update parent and component data
        root = unite(i, j)
        # After union, find updated root
        r = find(root)
        comp_load[r] = new_load
        # left endpoint is comp_left_node of old ri; right endpoint is comp_right_node of old rj
        comp_left_node[r] = comp_left_node[ri]
        comp_right_node[r] = comp_right_node[rj]
        # Ensure endpoints of non-root components are irrelevant; but keep consistent for find queries

    # Reconstruct component chains into routes
    routes = []
    used = set()
    for i in customers:
        ri = find(i)
        if ri in used:
            continue
        # find leftmost in component
        L = comp_left_node[ri]
        # If component could have been merged multiple times, leftmost is still the left endpoint
        # Build forward chain
        route = []
        cur = L
        while cur is not None:
            route.append(cur)
            used.add(find(cur))
            cur = succ[cur]
        if route:
            routes.append(route)

    # Any customer not yet in routes due to reconstruction issues: assign them greedily by best insertion
    in_routes = set()
    for r in routes:
        for v in r:
            in_routes.add(v)
    missing = [v for v in customers if v not in in_routes]

    # Best feasible insertion position into existing routes; if none feasible, create new route
    def best_insertion_pos(r, node):
        # returns (delta_cost, pos) where insert at pos in [0..len(r)]
        # Feasibility checked outside
        L = len(r)
        if L == 0:
            delta = matrix[depot][node] + matrix[node][depot]
            return delta, 0
        best = None
        # insert before r[0]
        delta = (matrix[depot][node] + matrix[node][r[0]] - matrix[depot][r[0]])
        best = (delta, 0)
        # insert between
        for k in range(L - 1):
            a, b = r[k], r[k + 1]
            delta = (matrix[a][node] + matrix[node][b] - matrix[a][b])
            if delta < best[0] or (delta == best[0] and k + 1 < best[1]):
                best = (delta, k + 1)
        # insert after r[-1]
        delta = (matrix[r[-1]][node] + matrix[node][depot] - matrix[r[-1]][depot])
        if delta < best[0] or (delta == best[0] and L < best[1]):
            best = (delta, L)
        return best

    for v in missing:
        best = None
        for idx, r in enumerate(routes):
            if route_load(r) + demands[v] <= capacity:
                delta, pos = best_insertion_pos(r, v)
                if best is None or delta < best[0] or (delta == best[0] and (idx, pos) < (best[1], best[2])):
                    best = (delta, idx, pos)
        if best is None:
            routes.append([v])
        else:
            _, idx, pos = best
            routes[idx] = routes[idx][:pos] + [v] + routes[idx][pos:]

    # Repair/cleanup: if any route violates capacity (shouldn't), split deterministically
    fixed = []
    for r in routes:
        if route_load(r) <= capacity:
            fixed.append(r)
            continue
        cur = []
        load = 0
        for v in r:
            if load + demands[v] <= capacity:
                cur.append(v)
                load += demands[v]
            else:
                fixed.append(cur)
                cur = [v]
                load = demands[v]
        if cur:
            fixed.append(cur)
    routes = fixed

    # Deterministic local improvement: relocate single node between routes (and within route) with capacity check
    # Keep it small to avoid instability.
    def relocate_best(routes):
        base_cost = total_cost(routes)
        best_move = None  # (delta, from_i, from_pos, to_j, to_pos)
        m = len(routes)
        for i in range(m):
            r1 = routes[i]
            if not r1:
                continue
            load1 = route_load(r1)
            for p in range(len(r1)):
                node = r1[p]
                load_without = load1 - demands[node]
                # Try inserting into other routes
                for j in range(m):
                    if i == j:
                        continue
                    r2 = routes[j]
                    if route_load(r2) + demands[node] > capacity:
                        continue
                    # compute delta if remove from i at p and insert into j at best pos position k
                    # We'll evaluate all insertion positions in r2
                    for q in range(len(r2) + 1):
                        # build delta carefully
                        # cost i remove
                        # neighbors in i:
                        before = r1[p - 1] if p - 1 >= 0 else depot
                        after = r1[p + 1] if p + 1 < len(r1) else depot
                        rem_delta = matrix[before][after] - (matrix[before][node] + matrix[node][after])

                        # cost j insert at q
                        if not r2:
                            ins_delta = matrix[depot][node] + matrix[node][depot]
                        else:
                            if q == 0:
                                ins_delta = matrix[depot][node] + matrix[node][r2[0]] - matrix[depot][r2[0]]
                            elif q == len(r2):
                                ins_delta = matrix[r2[-1]][node] + matrix[node][depot] - matrix[r2[-1]][depot]
                            else:
                                a, b = r2[q - 1], r2[q]
                                ins_delta = matrix[a][node] + matrix[node][b] - matrix[a][b]
                        delta = rem_delta + ins_delta
                        if delta < 0:
                            if best_move is None or delta < best_move[0]:
                                best_move = (delta, i, p, j, q)
        if best_move is not None:
            delta, i, p, j, q = best_move
            node = routes[i][p]
            routes[i] = routes[i][:p] + routes[i][p + 1:]
            if q > 0 and i == j and p < q:
                q -= 1
            r2 = routes[j]
            routes[j] = r2[:q] + [node] + r2[q:]
            # If route i becomes empty, remove it
            if not routes[i]:
                routes.pop(i)
            return True
        return False

    # Intra-route 2-opt within each route (deterministic, limited)
    def two_opt(routes):
        improved = False
        for idx in range(len(routes)):
            r = routes[idx]
            n = len(r)
            if n < 4:
                continue
            # limited search: first improvement
            best_delta = 0
            best_i = best_k = None
            for i in range(n - 1):
                a = r[i]
                b = r[i + 1] if i + 1 < n else depot
                for k in range(i + 2, n):
                    c = r[k - 1]
                    d = r[k] if k < n else depot
                    # consider reversing segment [i+1..k-1], affects edges (a-b) and (c-d)
                    if i + 1 >= k:
                        continue
                    # edges replaced: a->c and b->d
                    # old: a->b + c->d
                    # new: a->c + b->d
                    old = matrix[a][b] + matrix[c][d]
                    new = matrix[a][c] + matrix[b][d]
                    delta = new - old
                    if delta < best_delta or (delta == best_delta and (i, k) < (best_i, best_k)):
                        best_delta = delta
                        best_i, best_k = i, k
            if best_i is not None and best_delta < 0:
                i, k = best_i, best_k
                # reverse (i+1 ... k-1)
                newr = r[:i + 1] + r[i + 1:k][::-1] + r[k:]
                routes[idx] = newr
                improved = True
        return improved

    # Main improvement loop: a few deterministic passes using replay-aware order
    # (prefer inter-route relocation then 2-opt)
    for _ in range(3):
        if not two_opt(routes):
            # try relocation if no 2-opt improvements
            if not relocate_best(routes):
                break

    # Final feasibility split (safety)
    final_routes = []
    for r in routes:
        if not r:
            continue
        cur = []
        load = 0
        for v in r:
            if load + demands[v] <= capacity:
                cur.append(v)
                load += demands[v]
            else:
                if cur:
                    final_routes.append(cur)
                cur = [v]
                load = demands[v]
        if cur:
            final_routes.append(cur)

    return final_routes

